import csv

# Verify counts by manually counting from original file
with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)

    # Get indicator columns
    indicator_cols = header[3:]

    # Count missing for each indicator
    missing_counts = {}
    for ind in indicator_cols:
        missing_counts[ind] = 0

    for row in reader:
        for i, ind in enumerate(indicator_cols):
            if row[3+i] == '':
                missing_counts[ind] += 1

    print('Missing counts from manual verification:')
    for ind, count in sorted(missing_counts.items()):
        print(f'  {ind}: {count}')
""}

